import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/catalog/data/catalog_repository.dart';import 'package:pos_app/shared/presentation/database_list_screen.dart';class CategoriesScreen extends StatelessWidget{const CategoriesScreen({super.key});@override Widget build(BuildContext context)=>DatabaseListScreen(title:'Categorías',query:'SELECT id,name,description,active FROM categories ORDER BY name',action:(c)async{final v=await textForm(c,'Nueva categoría',['Nombre']);if(v!=null&&v.first.trim().isNotEmpty)await CatalogRepository(appDatabase).addCategory(v.first);});}
